import itertools

def valid_history(r, order):
    tx = {t['id']: t for t in r['transactions']}
    if not isinstance(order, list) or len(order) != len(tx) or set(order) != set(tx):
        return False
    ranks = {x: i for i, x in enumerate(order)}
    for a in tx.values():
        for b in tx.values():
            if a['end'] <= b['start'] and ranks[a['id']] >= ranks[b['id']]:
                return False
    d = r['initial'].copy()
    for name in order:
        for op in tx[name]['ops']:
            if op[0] == 'get':
                if d.get(op[1]) != op[2]:
                    return False
            elif op[0] == 'put':
                d[op[1]] = op[2]
            elif op[0] == 'del':
                d.pop(op[1], None)
            elif op[0] == 'cas':
                _, key, old, new, want = op
                ok = d.get(key) == old
                if ok is not want:
                    return False
                if ok:
                    if new is None:
